slides = [
 f'<div class="s dark"><h1>AuraZ</h1><p style="font-size:36px;max-width:1000px">Sepsis early warning you can explain, trust, and run beside the data on IBM Z.</p><p class="small" style="margin-top:36px">IBM Z Datathon 2026 · Technology for Good · github.com/saksham-2x7/IBM_Z</p><p class="small">Research prototype on retrospective data, not a medical device.</p></div>',
 '<div class="s"><h2>The problem</h2><ul><li>Sepsis is linked to about <b>11 million deaths a year</b> (WHO); every hour of delayed antibiotics lowers survival.</li><li>ICU alarms such as SIRS fire so often that staff <b>ignore them</b>.</li><li>Cloud AI moves <b>protected patient data</b> off-site and adds network delay.</li><li>Hospitals need warnings that are <b>earlier, rarer, explained, and honest about uncertainty</b>, running beside the data.</li></ul></div>',
 f'<div class="s"><h2>The solution</h2><div class="g c2"><div><ul><li>Scores every ICU patient <b>hourly</b>, predicts sepsis within 6 hours</li><li>Plain-language <b>explanation</b> for every alert</li><li>Conformal label: <b>sepsis not ruled out / uncertain / ruled out</b></li><li>Alert threshold under a <b>false-alarm budget</b></li></ul></div><div><ul><li><b>AuraZ-R</b>: 300 trees, 108 features, runs on CPU</li><li><b>AuraZ-N</b>: neural network, runs on the Telum II accelerator</li><li><b>200-bed ward</b> view, <b>FHIR</b> endpoint, alert log</li><li>{sim["cohorts"]["test"]:,}-stay simulated demo + {real["cohorts"]["train"]+real["cohorts"]["calibration"]+real["cohorts"]["test"]:,} real stays</li></ul></div></div></div>',
 f'<div class="s"><h2>Real ICU data results (PhysioNet 2019)</h2><div class="g c4">{kp(f"{real["auroc"]:.2f}", "AUROC, held-out stays (95% CI "+f"{real["auroc_ci95"][0]:.2f}–{real["auroc_ci95"][1]:.2f})")}{kp(f"{real["ablations"]["without_icu_time"]:.2f}", "AUROC without ICU-time features")}{kp(f"{m["sensitivity"]*100:.0f}% vs {real["alerting"]["baseline_sirs_rule"]["sensitivity"]*100:.0f}%", "septic patients caught, at SIRS’s alarm rate")}{kp(f"{sum(xs)/len(xs):.2f}", "AUROC at a different hospital")}</div><p style="margin-top:26px"><b>On all {full["cohorts"]["train"]+full["cohorts"]["calibration"]+full["cohorts"]["test"]:,} stays: AUROC {full["auroc"]:.2f}, {full["alerting"]["model_at_sirs_false_alert_rate"]["sensitivity"]*100:.0f}% vs {full["alerting"]["baseline_sirs_rule"]["sensitivity"]*100:.0f}% caught, other hospital {min(x["auroc"] for x in fa["cross_hospital"].values()):.2f}–{max(x["auroc"] for x in fa["cross_hospital"].values()):.2f}.</b> Our first model scored only <b>{real["baselines"]["logistic_16_features"]:.2f}</b> on real data, so we rebuilt it. We also report the drop at a new hospital: <b>each hospital must recalibrate</b>. Subgroup audit by sex and age is in the model card.</p></div>',
 f'<div class="s"><h2>Running on a real IBM z17 (Telum II)</h2><div class="g c4">{kp(f"{nn["timing"]["speedup_total_vs_cpu"]:.0f}×", "AuraZ-N on the NNPA accelerator vs a plain CPU loop")}{kp(f"{bl[0]["nnpa_speedup_total"]:.1f}×", "vs tuned OpenBLAS (1 thread); "+f"{bl[-1]["nnpa_speedup_total"]:.1f}× vs both threads")}{kp(f"{nn["auroc_on_nnpa"]:.4f}", "AUROC on the chip vs "+f"{nn["auroc_fp32_sklearn"]:.4f} FP32")}{kp(f"{lt["workers_2"]["peak"]["scores_per_s"]:,}", "scores/s peak, 2 vCPUs, 0.27 ms median")}</div><p style="margin-top:26px">{nn["rows"]:,} patient-hours: <b>{nn["timing"]["nnpa_total_ms"]:.1f} ms</b> on the accelerator vs {nn["timing"]["cpu_fp32_ms"]:.0f} ms plain loop, {bl[0]["ms"]:.1f} ms OpenBLAS. Honest limits: our tiny logistic model is <b>slower</b> on the accelerator, and the tree model stays on the CPU.</p></div>',
 '<div class="s"><h2>Architecture</h2><table><tr><th>Layer</th><th>What</th><th>Where</th></tr><tr><td>Data</td><td>PhysioNet 2019 real ICU stays; simulated look-alike cohort</td><td>ml/</td></tr><tr><td>Models</td><td>AuraZ-R trees, AuraZ-N neural network, conformal labels</td><td>Python, scikit-learn</td></tr><tr><td>Serving</td><td>Dependency-free service: /score_real, /fhir/score, alert log</td><td>IBM z17 (s390x)</td></tr><tr><td>Accelerator</td><td>AuraZ-N through IBM zDNN on the NNPA</td><td>C, Telum II</td></tr><tr><td>Clinician app</td><td>Live replay, 200-bed ward, validation, IBM Z panel</td><td>React + TypeScript</td></tr><tr><td>Quality</td><td>23 app tests, 6 server tests, 27 end-to-end checks, CI</td><td>Vitest, unittest, Actions</td></tr></table></div>',
 '<div class="s"><h2>Honest evaluation</h2><ul><li>Real-data first model: <b>0.61</b>; rebuilt model: <b>0.82</b>; at another hospital: <b>0.74</b></li><li>Uncertainty guarantee holds inside a hospital, <b>weakens across hospitals</b></li><li>Subgroup alert rates differ on small groups: flagged for follow-up</li><li>Uses 37% of PhysioNet 2019, retrospective only, no race/ethnicity data</li><li>Accelerator speed-up: 33× vs a plain loop, <b>1.2–1.5×</b> vs tuned OpenBLAS</li></ul></div>',
 '<div class="s dark"><h1 style="font-size:70px">Next</h1><p>All 40k stays and validation at another hospital · per-hospital recalibration · close the 0.02 AUROC gap between the neural and tree models · HL7/FHIR subscriptions · silent-mode clinical pilot</p><p style="margin-top:34px;font-size:28px"><b>AuraZ</b>: explainable, honest about uncertainty, built to run beside the data on IBM Z.</p><p class="small" style="margin-top:30px">Code: github.com/saksham-2x7/IBM_Z · Whitepaper, model card and accelerator report in /docs</p></div>',
]
